<script setup lang="ts">
import ConsoleDiscardChangesDialog from '../../components/console/ConsoleDiscardChangesDialog.vue'
import PackageThumbnail from '../../components/tenant/PackageThumbnail.vue'
import AdminConsole from '../../components/console/AdminConsole.vue'
import AccountImageInput from '../../components/console/AccountImageInput.vue'
import ConsoleDrawer from '../../components/console/ConsoleDrawer.vue'
import ConsoleQueryButton from '../../components/console/ConsoleQueryButton.vue'
import ConsolePageHeading from '@orangezh1/qisvc-console-ui/components/ConsolePageHeading'
import ConsoleDataTable from '@orangezh1/qisvc-console-ui/components/ConsoleDataTable'
import ConsoleListFilters from '@orangezh1/qisvc-console-ui/components/ConsoleListFilters'
import ConsoleListSearch from '@orangezh1/qisvc-console-ui/components/ConsoleListSearch'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsoleSettingsField from '@orangezh1/qisvc-console-ui/components/ConsoleSettingsField'
import ConsoleFormActions from '@orangezh1/qisvc-console-ui/components/ConsoleFormActions'
definePageMeta({layout:'tenant',key:route=>route.path})
type Benefit={optional?:boolean;key:string;label:string;unit:string;min:number;max:number}
type Package={image:string|null;badge:string;originalPriceCents:number|null;id:string;name:string;type:string;priceCents:number;currency:string;enabled:boolean;benefits:Record<string,number|null>}
type Catalog={currency:string;maxPriceCents:number;maxPackages:number;types:{key:string;label:string;fields:Benefit[]}[]}
type Listing={items:Package[];total:number;page:number;pageSize:number;version:number;applicationKey:string|null;applications:{key:string;name:string}[];catalog:Catalog|null;canWrite:boolean;developmentOnly?:boolean}
const auth=useApi('tenant'),tenantId=useTenantContext().tenantId.value,endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/packages',toast=useToast()
const q=ref(''),search=ref(''),kind=ref('all'),status=ref('all'),appliedKind=ref('all'),appliedStatus=ref('all'),applicationKey=ref(''),page=ref(1),pageSize=ref(20),busy=ref(false),loadAction=ref('initial')
const params=()=>new URLSearchParams({q:search.value,type:appliedKind.value,status:appliedStatus.value,page:String(page.value),pageSize:String(pageSize.value),...(applicationKey.value?{applicationKey:applicationKey.value}:{})})
const initial=await useAsyncData<Listing>('tenant-packages:'+auth.session.value?.id+':'+tenantId,(_nuxt,{signal})=>auth.api<Listing>(endpoint+'?'+params(),'GET',undefined,{signal}))
if(initial.error.value&&!auth.session.value)await navigateTo('/admin/login',{replace:true})
const rows=ref<Listing>(initial.data.value??{items:[],total:0,page:1,pageSize:20,version:0,applicationKey:null,applications:[],catalog:null,canWrite:false}),error=ref(initial.error.value?.message||'')
applicationKey.value=rows.value.applicationKey||''
const selected=ref<(string|number)[]>([]),mutation=ref<string|null>(null),editOpen=ref(false),editing=ref<Package|null>(null),formVersion=ref(0),formApplication=ref(''),requestId=ref(''),form=reactive({name:'',type:'',price:'',originalPrice:'',badge:'',image:null as string|null,enabled:true,benefits:{} as Record<string,number|string>}),formError=ref(''),imageBusy=ref(false)
const formBaseline=ref(''),formDirty=computed(()=>editOpen.value&&JSON.stringify(form)!==formBaseline.value),discard=useDiscardChanges(()=>!!mutation.value||imageBusy.value)
function closeEditor(){if(mutation.value||imageBusy.value)return;if(formDirty.value){discard.request(()=>{editOpen.value=false});return}editOpen.value=false}
const fields=computed(()=>rows.value.catalog?.types.find(type=>type.key===form.type)?.fields||[])
const deleteOpen=ref(false),deleteIds=ref<string[]>([]),deleteVersion=ref(0),deleteError=ref('')
const columns=[{accessorKey:'name',header:'套餐名称'},{accessorKey:'type',header:'套餐类型'},{accessorKey:'priceCents',header:'售价（元）'},{id:'benefits',header:'权益规格'},{accessorKey:'enabled',header:'状态'},{id:'actions',header:'操作'}]
const money=(cents:number)=>(Math.trunc(cents/100)).toLocaleString('zh-CN')+'.'+String(cents%100).padStart(2,'0')
const typeLabel=(key:string)=>rows.value.catalog?.types.find(type=>type.key===key)?.label||key
const packageFields=(pkg:Package)=>rows.value.catalog?.types.find(type=>type.key===pkg.type)?.fields||[]
const lifetime=new AbortController();let disposed=false,sequence=0,controller:AbortController|undefined
async function load(source='refresh'){
 if(disposed)return;controller?.abort();controller=new AbortController();const current=++sequence;busy.value=true;loadAction.value=source
 try{const value=await auth.api<Listing>(endpoint+'?'+params(),'GET',undefined,{signal:AbortSignal.any([lifetime.signal,controller.signal])});if(!disposed&&current===sequence){rows.value=value;page.value=value.page;applicationKey.value=value.applicationKey||'';selected.value=[];error.value=''}}catch(e:any){if(!disposed&&current===sequence){error.value=e.message||'套餐读取失败';if(e.status===401)await navigateTo('/admin/login',{replace:true})}}finally{if(!disposed&&current===sequence)busy.value=false}
}
function filter(source:'search'|'reset'){if(mutation.value)return;if(source==='reset'){q.value='';kind.value='all';status.value='all'}search.value=q.value.trim();appliedKind.value=kind.value;appliedStatus.value=status.value;page.value=1;void load(source)}
function setPage(value:number){if(value===page.value||mutation.value)return;page.value=value;void load('page')}
function setPageSize(value:number){if(value===pageSize.value||mutation.value)return;pageSize.value=value;page.value=1;void load('page')}
function chooseApplication(value:string){if(mutation.value)return;applicationKey.value=value;editOpen.value=false;deleteOpen.value=false;kind.value='all';appliedKind.value='all';page.value=1;rows.value={...rows.value,items:[],total:0,version:0,catalog:null,canWrite:false,applicationKey:null};selected.value=[];void load('application')}
function changeType(){form.benefits=Object.fromEntries(fields.value.map(field=>[field.key,field.optional?'':field.min]))}
function openEditor(row:Package|null=null){
 if(mutation.value||!rows.value.canWrite||!rows.value.applicationKey||!rows.value.catalog)return
 editing.value=row;formVersion.value=rows.value.version;formApplication.value=rows.value.applicationKey;requestId.value=crypto.randomUUID();form.name=row?.name||'';form.type=row?.type||rows.value.catalog.types[0]?.key||'';form.price=row?String(Math.trunc(row.priceCents/100))+'.'+String(row.priceCents%100).padStart(2,'0'):'';form.originalPrice=row?.originalPriceCents?String(Math.trunc(row.originalPriceCents/100))+'.'+String(row.originalPriceCents%100).padStart(2,'0'):'';form.badge=row?.badge||'';form.image=row?.image||null;form.enabled=row?.enabled??true;form.benefits=row?Object.fromEntries(Object.entries(row.benefits).map(([key,value])=>[key,value??''])):{};if(!row)changeType();formError.value='';formBaseline.value=JSON.stringify(form);editOpen.value=true
}
async function save(){
 if(mutation.value||imageBusy.value||!rows.value.canWrite||!rows.value.catalog)return
 const price=form.price.trim();if(!/^(0|[1-9]\d{0,6})(\.\d{1,2})?$/.test(price)){formError.value='请输入有效价格，最多两位小数';return}
 const [whole,fraction='']=price.split('.'),priceCents=Number(whole)*100+Number(fraction.padEnd(2,'0')),benefits=Object.fromEntries(fields.value.map(field=>[field.key,field.optional&&(form.benefits[field.key]===''||form.benefits[field.key]==null)?null:Number(form.benefits[field.key])]))
 if(!form.name.trim()||priceCents<1||priceCents>rows.value.catalog.maxPriceCents||!fields.value.length||fields.value.some(field=>!(field.optional&&benefits[field.key]===null)&&(!Number.isSafeInteger(benefits[field.key])||benefits[field.key]!<field.min||benefits[field.key]!>field.max))){formError.value='请检查名称、价格、积分和有效天数的范围';return}
 const original=form.originalPrice.trim();if(original&&!/^(0|[1-9]\d{0,6})(\.\d{1,2})?$/.test(original)){formError.value='原价最多保留两位小数';return}
 const [originalWhole,originalFraction='']=original.split('.'),originalPriceCents=original?Number(originalWhole)*100+Number(originalFraction.padEnd(2,'0')):null;if(originalPriceCents!==null&&(originalPriceCents<priceCents||originalPriceCents>rows.value.catalog.maxPriceCents)){formError.value='原价不能低于售价或超出价格上限';return}
 mutation.value='save';formError.value=''
 try{const path=endpoint+'/'+encodeURIComponent(formApplication.value)+(editing.value?'/'+encodeURIComponent(editing.value.id):'');await auth.api(path,editing.value?'PUT':'POST',{version:formVersion.value,...(!editing.value?{requestId:requestId.value}:{}),package:{name:form.name.trim(),type:form.type,priceCents,originalPriceCents,badge:form.badge.trim(),image:form.image,enabled:form.enabled,benefits}},{signal:lifetime.signal});if(!disposed){editOpen.value=false;toast.add({title:'套餐已保存',color:'success'});await load('mutation')}}catch(e){if(!disposed)formError.value=e instanceof Error?e.message:'保存失败'}finally{if(!disposed)mutation.value=null}
}
async function toggle(row:Package){
 if(mutation.value||!rows.value.canWrite||!rows.value.applicationKey)return;mutation.value='status:'+row.id;error.value=''
 try{await auth.api(endpoint+'/'+encodeURIComponent(rows.value.applicationKey)+'/'+encodeURIComponent(row.id)+'/status','PUT',{version:rows.value.version,enabled:!row.enabled},{signal:lifetime.signal});if(!disposed)await load('mutation')}catch(e){if(!disposed)error.value=e instanceof Error?e.message:'状态修改失败'}finally{if(!disposed)mutation.value=null}
}
function askDelete(row?:Package){if(mutation.value||!rows.value.canWrite)return;deleteIds.value=row?[row.id]:rows.value.items.filter(item=>selected.value.includes(item.id)).map(item=>item.id);if(!deleteIds.value.length)return;deleteVersion.value=rows.value.version;deleteError.value='';deleteOpen.value=true}
async function remove(){
 if(mutation.value||!rows.value.applicationKey||!deleteIds.value.length)return;mutation.value='delete';deleteError.value=''
 try{await auth.api(endpoint+'/'+encodeURIComponent(rows.value.applicationKey)+'/delete','POST',{version:deleteVersion.value,ids:deleteIds.value},{signal:lifetime.signal});if(!disposed){deleteOpen.value=false;selected.value=[];toast.add({title:'套餐已删除',color:'success'});await load('mutation')}}catch(e){if(!disposed)deleteError.value=e instanceof Error?e.message:'删除失败'}finally{if(!disposed)mutation.value=null}
}
onBeforeRouteLeave(to=>{if(mutation.value||imageBusy.value){toast.add({title:'正在处理，请稍候再离开',color:'neutral'});return false}if(formDirty.value){discard.request(()=>{editOpen.value=false;void navigateTo(to.fullPath)});return false}})
onBeforeUnmount(()=>{disposed=true;sequence++;controller?.abort();lifetime.abort();busy.value=false})
</script>
<template><AdminConsole :refreshing="busy&&loadAction==='refresh'" @refresh="load('refresh')"><div class="space-y-5">
 <ConsolePageHeading title="套餐管理"><template #actions><UBadge v-if="rows.developmentOnly" color="warning" variant="subtle">开发配置</UBadge><UButton v-if="rows.canWrite" icon="i-lucide-plus" :disabled="!!mutation||!rows.applicationKey" @click="openEditor()">新建套餐</UButton></template></ConsolePageHeading>
 <form @submit.prevent="filter('search')"><ConsoleListFilters><ConsoleListSearch v-model="q" placeholder="搜索套餐名称" :maxlength="100" :disabled="!!mutation"/><USelect v-if="rows.applications.length>1" :model-value="applicationKey" :items="rows.applications.map(app=>({label:app.name,value:app.key}))" placeholder="选择应用" aria-label="套餐所属应用" :disabled="!!mutation" @update:model-value="chooseApplication"/><USelect v-model="kind" :items="[{value:'all',label:'全部套餐类型'},...(rows.catalog?.types.map(type=>({value:type.key,label:type.label}))||[])]" aria-label="套餐类型" :disabled="!!mutation"/><USelect v-model="status" :items="[{value:'all',label:'全部状态'},{value:'enabled',label:'启用'},{value:'disabled',label:'停用'}]" aria-label="套餐状态" :disabled="!!mutation"/><div class="flex shrink-0 items-center gap-3"><ConsoleQueryButton type="submit" :loading="busy&&loadAction==='search'" :disabled="!!mutation">查询</ConsoleQueryButton><ConsoleQueryButton kind="reset" color="neutral" variant="outline" :loading="busy&&loadAction==='reset'" :disabled="!!mutation" @click="filter('reset')">重置</ConsoleQueryButton></div></ConsoleListFilters></form>
 <ConsoleDataTable v-model:selected-ids="selected" :selectable="rows.canWrite" :data="rows.items" :columns="columns" :page="page" :page-size="pageSize" :page-size-items="[10,20,50]" :total="rows.total" :client-pagination="false" :error="error" :empty-title="!rows.applicationKey&&rows.applications.length>1?'请选择应用':'暂无匹配的套餐'" empty-description="可以新建套餐，或调整筛选条件。" min-table-width="1020px" @retry="load('retry')" @update:page="setPage" @update:page-size="setPageSize">
  <template #errorActions><UButton :loading="busy&&loadAction==='retry'" @click="load('retry')">重试</UButton></template>
  <template #selection="{selectedCount}"><UButton color="error" variant="outline" icon="i-lucide-trash-2" :disabled="!selectedCount||!!mutation" @click="askDelete()">批量删除（{{selectedCount}}）</UButton></template>
  <template #name-cell="{row}"><div class="flex min-w-56 items-center gap-4"><PackageThumbnail :image="row.original.image" :name="row.original.name" :badge="row.original.badge"/><span class="block max-w-44 truncate font-medium" :title="row.original.name">{{row.original.name}}</span></div></template>
  <template #type-cell="{row}"><span class="whitespace-nowrap">{{typeLabel(row.original.type)}}</span></template>
  <template #priceCents-cell="{row}"><span class="whitespace-nowrap font-semibold tabular-nums">{{money(row.original.priceCents)}}</span><p v-if="row.original.originalPriceCents" class="mt-1 text-xs text-muted">原价 <span class="line-through">{{money(row.original.originalPriceCents)}}</span></p></template>
  <template #benefits-cell="{row}"><div class="space-y-1 text-xs text-muted"><p v-for="field in packageFields(row.original)" :key="field.key">{{field.label}}：<span class="text-default">{{field.optional&&row.original.benefits[field.key]==null?'长期有效':row.original.benefits[field.key]+' '+field.unit}}</span></p></div></template>
  <template #enabled-cell="{row}"><UBadge :color="row.original.enabled?'success':'neutral'" variant="subtle">{{row.original.enabled?'启用':'停用'}}</UBadge></template>
  <template #actions-cell="{row}"><div v-if="rows.canWrite" class="flex items-center gap-3 whitespace-nowrap"><UButton size="sm" variant="link" class="px-0" :disabled="!!mutation" @click="openEditor(row.original)">编辑</UButton><UButton size="sm" variant="link" class="px-0" :loading="mutation==='status:'+row.original.id" :disabled="!!mutation" @click="toggle(row.original)">{{row.original.enabled?'停用':'启用'}}</UButton><UButton size="sm" color="error" variant="link" class="px-0" :disabled="!!mutation" @click="askDelete(row.original)">删除</UButton></div><span v-else class="text-xs text-muted">只读</span></template>
 </ConsoleDataTable>
 <ConsoleDrawer :open="editOpen" @update:open="!$event&&closeEditor()" :title="editing?'编辑套餐':'新建套餐'" description="修改只影响后续下单，已下单的价格与权益保持原样。" :dismissible="!mutation&&!imageBusy" :close="!mutation&&!imageBusy" wide><template #body><form id="package-form" class="package-form space-y-6" @submit.prevent="save"><UAlert v-if="formError" color="error" :title="formError"/><ConsoleSettingsField label="套餐图片"><AccountImageInput v-model="form.image" label="套餐图片" portal="tenant" :endpoint="'/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/'+encodeURIComponent(rows.applicationKey||'')" fit="contain" :image-size="512" fallback="" :disabled="!!mutation" @busy="imageBusy=$event"/></ConsoleSettingsField><ConsoleSettingsField label="角标" input-id="package-badge"><ConsoleInput id="package-badge" v-model="form.badge" :maxlength="12" :disabled="!!mutation" placeholder="例如：推荐、热销（选填）"/></ConsoleSettingsField><ConsoleSettingsField label="套餐名称" input-id="package-name"><ConsoleInput id="package-name" v-model="form.name" :maxlength="64" required :disabled="!!mutation" placeholder="请输入套餐名称"/></ConsoleSettingsField><ConsoleSettingsField label="套餐类型" input-id="package-type"><USelect id="package-type" v-model="form.type" :items="rows.catalog?.types.map(type=>({value:type.key,label:type.label}))||[]" :disabled="!!editing||!!mutation" class="w-full" @update:model-value="changeType"/></ConsoleSettingsField><ConsoleSettingsField label="售价（元）" input-id="package-price"><ConsoleInput id="package-price" v-model="form.price" inputmode="decimal" required :disabled="!!mutation" placeholder="例如：19.90"/><p class="mt-2 text-xs text-muted">最低 0.01 元，最多两位小数。</p></ConsoleSettingsField><ConsoleSettingsField label="原价（元）" input-id="package-original-price"><ConsoleInput id="package-original-price" v-model="form.originalPrice" inputmode="decimal" :disabled="!!mutation" placeholder="选填，不能低于售价"/></ConsoleSettingsField><h3 class="drawer-form-section">积分与会员</h3><p class="text-xs text-muted">有效期留空表示长期有效。</p><ConsoleSettingsField v-for="field in fields" :key="field.key" :label="field.unit==='积分'?field.label:field.label+'（'+field.unit+'）'" :input-id="'package-'+field.key"><ConsoleInput :id="'package-'+field.key" v-model="form.benefits[field.key]" type="number" :min="field.min" :max="field.max" :step="1" :required="!field.optional" :placeholder="field.optional?'不限制':'请输入积分数量'" :disabled="!!mutation"/></ConsoleSettingsField><ConsoleSettingsField label="套餐状态"><USwitch v-model="form.enabled" :label="form.enabled?'启用':'停用'" :disabled="!!mutation"/><p class="mt-2 text-xs text-muted">停用后不再接受新下单，已有订单和权益不受影响。</p></ConsoleSettingsField></form></template><template #footer><ConsoleFormActions class="w-full"><UButton color="neutral" variant="outline" :disabled="!!mutation||imageBusy" @click="closeEditor">取消</UButton><UButton type="submit" form="package-form" :loading="mutation==='save'" :disabled="!!mutation||imageBusy">保存</UButton></ConsoleFormActions></template></ConsoleDrawer>
 <UModal v-model:open="deleteOpen" title="删除套餐？" description="删除后不能再购买该套餐，已有订单及已获得的权益保留。" :dismissible="!mutation" :close="!mutation"><template #body><p>将删除 {{deleteIds.length}} 个套餐。</p><UAlert v-if="deleteError" class="mt-4" color="error" :title="deleteError"/></template><template #footer><div class="flex w-full justify-end gap-3"><UButton color="neutral" variant="outline" :disabled="!!mutation" @click="deleteOpen=false">取消</UButton><UButton color="error" :loading="mutation==='delete'" :disabled="!!mutation" @click="remove">确认删除</UButton></div></template></UModal>
<ConsoleDiscardChangesDialog :controller="discard"/>
</div></AdminConsole></template>
<style scoped>.package-form{--settings-label-width:9rem;--settings-content-width:32rem}</style>
